llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In healthy volunteers, baclofen absolute oral bioavailability was 81.2% at a 20 mg dose, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Doravirine oral bioavailability is 64% after a 100-mg tablet and is not significantly affected by food, supporting high F under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Alprazolam overall oral bioavailability was estimated at 0.84 from clinical oral versus IV data, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence molecules support high oral bioavailability, with numeric absolute F values mostly 63–92% and qualitative reports of good/excellent availability; no evidence falls below 20%. Fed-state-relevant notes show either no significant food effect or reduced but still high absorption, so the prediction is high.",
  "evidence_gaps": [
    "No direct fed-state absolute bioavailability measurement was supplied; food-effect evidence is indirect from transferred molecules.",
    "Some transferred records are qualitative rather than numeric absolute F values.",
    "Triazolam records vary widely, but all remain above the 20% threshold, so the variability is not threshold-relevant."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

